/**
 * Publish Twyne folios to Standard.site records in the writer's own PDS.
 *
 * The PDS is the source of truth. Twyne only keeps record keys in local IDB
 * so a re-publish updates the same records and an unpublish can remove the
 * document again. Public reading and verification routes derive their lookup
 * directly from the AT-URI encoded in the canonical Twyne URL.
 */

import type { Agent } from "@atproto/api";
import type { Folio, ProjectBrief } from "../types";
import { htmlToMarkdown, stripHtml } from "./exchange";
import { loadMetaFromIdb, saveMetaToIdb } from "./idb";
import {
  STANDARD_SITE_DOCUMENT_COLLECTION,
  STANDARD_SITE_ORIGIN,
  STANDARD_SITE_PUBLICATION_COLLECTION,
  parseAtUri,
  standardSiteDocumentPath,
  standardSiteDocumentUrl,
  standardSitePublicationUrl,
} from "./standard-site-paths";

const PUBLICATION_META_KEY = "atproto-publication";
const docMetaKey = (folioId: string) => `atproto-doc-${folioId}`;

export interface PublicationRef {
  uri: string;
  name: string;
  url: string;
}

interface DocumentRef {
  uri: string;
  rkey: string;
  publicationUri?: string;
  /** ISO timestamp of the first publish, preserved across re-publishes. */
  publishedAt: string;
}

export interface PublishResult {
  /** The document's at:// URI. */
  uri: string;
  /** The publication record this document belongs to. */
  publicationUri: string;
  /** A human-openable, Standard.site-verifiable reading URL. */
  viewerUrl: string;
  /** Fallback explorer URL that works for any record. */
  explorerUrl: string;
}

type UnknownRecord = Record<string, unknown>;

function repoDid(agent: Agent): string {
  const did = (agent as Agent & { did?: string }).did ?? agent.assertDid;
  if (!did) throw new Error("Agent has no DID");
  return did;
}

function rkeyFromUri(uri: string, collection: string): string {
  const parsed = parseAtUri(uri);
  if (!parsed || parsed.collection !== collection) {
    throw new Error(`PDS returned an invalid ${collection} URI`);
  }
  return parsed.rkey;
}

function publicationRecord(
  current: UnknownRecord | null,
  opts: { name: string; url: string },
): UnknownRecord {
  return {
    ...(current ?? {}),
    $type: STANDARD_SITE_PUBLICATION_COLLECTION,
    name: opts.name,
    url: opts.url,
    preferences:
      current?.preferences && typeof current.preferences === "object"
        ? current.preferences
        : { showInDiscover: true },
  };
}

function documentRecord(opts: {
  folio: Folio;
  html: string;
  brief: ProjectBrief | null;
  publicationUri: string;
  publishedAt: string;
  updatedAt: string;
  path?: string;
}): UnknownRecord {
  const title = opts.folio.name || opts.brief?.answers.workingTitle || "Untitled";
  const description = opts.brief?.answers.goal?.trim() || undefined;
  const markdown = htmlToMarkdown(opts.html);

  return {
    $type: STANDARD_SITE_DOCUMENT_COLLECTION,
    site: opts.publicationUri,
    title,
    ...(opts.path ? { path: opts.path } : {}),
    publishedAt: opts.publishedAt,
    updatedAt: opts.updatedAt,
    ...(description ? { description } : {}),
    textContent: stripHtml(opts.html),
    content: {
      $type: "at.markpub.markdown",
      text: {
        $type: "at.markpub.text",
        markdown,
      },
      flavor: "gfm",
      renderingRules: "marked",
    },
  };
}

async function putPublication(
  agent: Agent,
  uri: string,
  name: string,
): Promise<PublicationRef> {
  const parsed = parseAtUri(uri);
  if (
    !parsed ||
    parsed.collection !== STANDARD_SITE_PUBLICATION_COLLECTION ||
    parsed.did !== repoDid(agent)
  ) {
    throw new Error("Cached Standard.site publication does not belong to this PDS");
  }

  let current: UnknownRecord | null = null;
  try {
    const existing = await agent.com.atproto.repo.getRecord({
      repo: parsed.did,
      collection: STANDARD_SITE_PUBLICATION_COLLECTION,
      rkey: parsed.rkey,
    });
    current = existing.data.value as UnknownRecord;
  } catch {
    // A stale local cache is allowed to recreate its deterministic record.
  }

  const url = standardSitePublicationUrl(parsed.did, parsed.rkey);
  await agent.com.atproto.repo.putRecord({
    repo: parsed.did,
    collection: STANDARD_SITE_PUBLICATION_COLLECTION,
    rkey: parsed.rkey,
    record: publicationRecord(current, { name, url }),
  });

  const ref = { uri, name, url };
  await saveMetaToIdb(PUBLICATION_META_KEY, ref);
  return ref;
}

/** Find, migrate, or create the writer's Twyne Standard.site publication. */
export async function ensurePublication(
  agent: Agent,
  opts: { name: string },
): Promise<PublicationRef> {
  const cached = await loadMetaFromIdb<PublicationRef>(PUBLICATION_META_KEY);
  if (cached?.uri) {
    try {
      return await putPublication(agent, cached.uri, opts.name);
    } catch {
      await saveMetaToIdb(PUBLICATION_META_KEY, null);
    }
  }

  const did = repoDid(agent);
  try {
    const existing = await agent.com.atproto.repo.listRecords({
      repo: did,
      collection: STANDARD_SITE_PUBLICATION_COLLECTION,
      limit: 100,
    });
    const candidate = existing.data.records.find((entry) => {
      const value = entry.value as { url?: unknown };
      if (typeof value.url !== "string") return false;
      return (
        value.url === STANDARD_SITE_ORIGIN ||
        value.url.startsWith(`${STANDARD_SITE_ORIGIN}/at/`)
      );
    });
    if (candidate) return await putPublication(agent, candidate.uri, opts.name);
  } catch {
    // The collection may not exist yet. Creation below is the normal path.
  }

  // createRecord supplies the TID. We immediately put the same record with
  // its canonical URL once that key is known.
  const created = await agent.com.atproto.repo.createRecord({
    repo: did,
    collection: STANDARD_SITE_PUBLICATION_COLLECTION,
    record: publicationRecord(null, {
      name: opts.name,
      url: STANDARD_SITE_ORIGIN,
    }),
  });
  return await putPublication(agent, created.data.uri, opts.name);
}

/** Publish or update one folio as a Standard.site document. */
export async function publishDocument(
  agent: Agent,
  opts: {
    folio: Folio;
    html: string;
    brief: ProjectBrief | null;
    publication: PublicationRef;
  },
): Promise<PublishResult> {
  const { folio, html, brief, publication } = opts;
  const did = repoDid(agent);
  const publicationParts = parseAtUri(publication.uri);
  if (
    !publicationParts ||
    publicationParts.did !== did ||
    publicationParts.collection !== STANDARD_SITE_PUBLICATION_COLLECTION
  ) {
    throw new Error("Standard.site publication does not belong to this PDS");
  }

  const now = new Date().toISOString();
  const prior = await loadMetaFromIdb<DocumentRef>(docMetaKey(folio.id));
  const publishedAt = prior?.publishedAt || now;

  let uri: string;
  let rkey: string;
  if (prior?.rkey) {
    rkey = prior.rkey;
    const result = await agent.com.atproto.repo.putRecord({
      repo: did,
      collection: STANDARD_SITE_DOCUMENT_COLLECTION,
      rkey,
      record: documentRecord({
        folio,
        html,
        brief,
        publicationUri: publication.uri,
        path: standardSiteDocumentPath(rkey),
        publishedAt,
        updatedAt: now,
      }),
    });
    uri = result.data.uri;
  } else {
    const created = await agent.com.atproto.repo.createRecord({
      repo: did,
      collection: STANDARD_SITE_DOCUMENT_COLLECTION,
      record: documentRecord({
        folio,
        html,
        brief,
        publicationUri: publication.uri,
        publishedAt,
        updatedAt: now,
      }),
    });
    uri = created.data.uri;
    rkey = rkeyFromUri(uri, STANDARD_SITE_DOCUMENT_COLLECTION);
    const updated = await agent.com.atproto.repo.putRecord({
      repo: did,
      collection: STANDARD_SITE_DOCUMENT_COLLECTION,
      rkey,
      record: documentRecord({
        folio,
        html,
        brief,
        publicationUri: publication.uri,
        path: standardSiteDocumentPath(rkey),
        publishedAt,
        updatedAt: now,
      }),
    });
    uri = updated.data.uri;
  }

  const ref: DocumentRef = {
    uri,
    rkey,
    publicationUri: publication.uri,
    publishedAt,
  };
  await saveMetaToIdb(docMetaKey(folio.id), ref);

  const viewerUrl = standardSiteDocumentUrl(
    did,
    publicationParts.rkey,
    rkey,
  );
  return {
    uri,
    publicationUri: publication.uri,
    viewerUrl,
    explorerUrl: `https://pdsls.dev/${encodeURIComponent(uri)}`,
  };
}

/** Return the locally-known PDS publication state for a folio, if any. */
export async function loadPublishedDocument(
  folioId: string,
): Promise<PublishResult | null> {
  const doc = await loadMetaFromIdb<DocumentRef>(docMetaKey(folioId));
  const publication = await loadMetaFromIdb<PublicationRef>(
    PUBLICATION_META_KEY,
  );
  if (!doc?.uri || !publication?.uri) return null;
  const documentParts = parseAtUri(doc.uri);
  const publicationParts = parseAtUri(publication.uri);
  if (
    !documentParts ||
    !publicationParts ||
    documentParts.did !== publicationParts.did
  ) {
    return null;
  }
  return {
    uri: doc.uri,
    publicationUri: publication.uri,
    viewerUrl: standardSiteDocumentUrl(
      documentParts.did,
      publicationParts.rkey,
      documentParts.rkey,
    ),
    explorerUrl: `https://pdsls.dev/${encodeURIComponent(doc.uri)}`,
  };
}

/** Delete the folio's Standard.site document from the writer's PDS. */
export async function unpublishDocument(
  agent: Agent,
  folioId: string,
): Promise<boolean> {
  const prior = await loadMetaFromIdb<DocumentRef>(docMetaKey(folioId));
  if (!prior?.uri) return false;
  const parsed = parseAtUri(prior.uri);
  if (
    !parsed ||
    parsed.did !== repoDid(agent) ||
    parsed.collection !== STANDARD_SITE_DOCUMENT_COLLECTION
  ) {
    throw new Error("Published Standard.site document does not belong to this PDS");
  }
  await agent.com.atproto.repo.deleteRecord({
    repo: parsed.did,
    collection: STANDARD_SITE_DOCUMENT_COLLECTION,
    rkey: parsed.rkey,
  });
  await saveMetaToIdb(docMetaKey(folioId), null);
  return true;
}
import { marked, Renderer } from "marked";
import {
  STANDARD_SITE_DOCUMENT_COLLECTION,
  STANDARD_SITE_PUBLICATION_COLLECTION,
  decodeStandardSiteDid,
  documentAtUri,
  isTid,
  publicationAtUri,
  standardSiteDocumentPath,
  standardSiteDocumentUrl,
  standardSitePublicationUrl,
} from "./standard-site-paths";

const MAX_RECORD_BYTES = 1_050_000;
const REQUEST_TIMEOUT_MS = 7_000;
const PLC_DID_RE = /^did:plc:[a-z2-7]{24}$/;

type Fetcher = (
  input: string | URL | Request,
  init?: RequestInit,
) => Promise<Response>;
type UnknownRecord = Record<string, unknown>;

export interface StandardSitePublication {
  uri: string;
  did: string;
  rkey: string;
  name: string;
  description: string | null;
  url: string;
}

export interface StandardSiteDocumentSummary {
  uri: string;
  rkey: string;
  title: string;
  description: string | null;
  publishedAt: string;
  updatedAt: string | null;
  url: string;
}

export interface StandardSiteDocument extends StandardSiteDocumentSummary {
  textContent: string;
  markdown: string | null;
  html: string;
}

export interface StandardSitePublicationPage {
  publication: StandardSitePublication;
  documents: StandardSiteDocumentSummary[];
}

export interface StandardSiteDocumentPage {
  publication: StandardSitePublication;
  document: StandardSiteDocument;
}

function recordObject(value: unknown): UnknownRecord | null {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as UnknownRecord)
    : null;
}

function stringField(record: UnknownRecord, key: string): string | null {
  const value = record[key];
  return typeof value === "string" ? value : null;
}

function safeServiceEndpoint(value: unknown): string | null {
  if (typeof value !== "string") return null;
  try {
    const url = new URL(value);
    const host = url.hostname.toLowerCase();
    if (url.protocol !== "https:" || url.username || url.password) return null;
    if (
      host === "localhost" ||
      host.endsWith(".localhost") ||
      host.endsWith(".local") ||
      host.endsWith(".internal") ||
      /^\d{1,3}(?:\.\d{1,3}){3}$/.test(host) ||
      host.startsWith("[")
    ) {
      return null;
    }
    return url.origin;
  } catch {
    return null;
  }
}

async function fetchJson(
  url: string | URL,
  fetcher: Fetcher,
): Promise<unknown> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const response = await fetcher(url, {
      headers: { Accept: "application/json" },
      redirect: "error",
      signal: controller.signal,
    });
    if (!response.ok) throw new Error(`ATProto request failed (${response.status})`);
    const declaredSize = Number(response.headers.get("content-length") ?? 0);
    if (declaredSize > MAX_RECORD_BYTES) throw new Error("ATProto record is too large");
    const text = await response.text();
    if (text.length > MAX_RECORD_BYTES) throw new Error("ATProto record is too large");
    return JSON.parse(text) as unknown;
  } finally {
    clearTimeout(timeout);
  }
}

async function resolvePds(did: string, fetcher: Fetcher): Promise<string> {
  // PLC identities cover Bluesky and self-hosted PDS users while keeping DID
  // resolution on one trusted origin. did:web support would require a fully
  // DNS-aware SSRF defence before it is safe to add to a server-side reader.
  if (!PLC_DID_RE.test(did)) throw new Error("Unsupported ATProto DID");
  const document = recordObject(
    await fetchJson(`https://plc.directory/${encodeURIComponent(did)}`, fetcher),
  );
  const services = Array.isArray(document?.service) ? document.service : [];
  for (const candidate of services) {
    const service = recordObject(candidate);
    if (
      service?.type !== "AtprotoPersonalDataServer" &&
      service?.id !== "#atproto_pds"
    ) {
      continue;
    }
    const endpoint = safeServiceEndpoint(service?.serviceEndpoint);
    if (endpoint) return endpoint;
  }
  throw new Error("ATProto PDS service is unavailable");
}

async function getRecord(
  did: string,
  collection: string,
  rkey: string,
  fetcher: Fetcher,
  pds?: string,
): Promise<UnknownRecord> {
  const endpoint = pds ?? (await resolvePds(did, fetcher));
  const url = new URL("/xrpc/com.atproto.repo.getRecord", endpoint);
  url.searchParams.set("repo", did);
  url.searchParams.set("collection", collection);
  url.searchParams.set("rkey", rkey);
  const envelope = recordObject(await fetchJson(url, fetcher));
  const value = recordObject(envelope?.value);
  if (!value) throw new Error("ATProto record is malformed");
  return value;
}

async function listDocumentRecords(
  did: string,
  fetcher: Fetcher,
  pds: string,
): Promise<Array<{ uri: string; value: UnknownRecord }>> {
  const url = new URL("/xrpc/com.atproto.repo.listRecords", pds);
  url.searchParams.set("repo", did);
  url.searchParams.set("collection", STANDARD_SITE_DOCUMENT_COLLECTION);
  url.searchParams.set("limit", "100");
  url.searchParams.set("reverse", "true");
  const envelope = recordObject(await fetchJson(url, fetcher));
  const records = Array.isArray(envelope?.records) ? envelope.records : [];
  return records.flatMap((candidate) => {
    const entry = recordObject(candidate);
    const uri = typeof entry?.uri === "string" ? entry.uri : null;
    const value = recordObject(entry?.value);
    return uri && value ? [{ uri, value }] : [];
  });
}

function parsePublication(
  did: string,
  rkey: string,
  value: UnknownRecord,
): StandardSitePublication {
  const uri = publicationAtUri(did, rkey);
  const expectedUrl = standardSitePublicationUrl(did, rkey);
  const name = stringField(value, "name")?.trim();
  const url = stringField(value, "url")?.replace(/\/$/, "");
  if (
    value.$type !== STANDARD_SITE_PUBLICATION_COLLECTION ||
    !name ||
    url !== expectedUrl
  ) {
    throw new Error("Standard.site publication is not verified for this URL");
  }
  return {
    uri,
    did,
    rkey,
    name,
    description: stringField(value, "description")?.trim() || null,
    url,
  };
}

function safeHref(value: string, image = false): string | null {
  const trimmed = value.trim();
  if (/^(?:\/|#|\.\/|\.\.\/)/.test(trimmed)) return trimmed;
  try {
    const url = new URL(trimmed);
    if (url.protocol === "http:" || url.protocol === "https:") return trimmed;
    if (!image && url.protocol === "mailto:") return trimmed;
  } catch {
    // Invalid and non-relative URLs are deliberately dropped.
  }
  return null;
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function renderStandardSiteMarkdown(markdown: string): string {
  const renderer = new Renderer();
  renderer.html = ({ text }) => escapeHtml(text);
  renderer.link = function ({ href, title, tokens }) {
    const label = this.parser.parseInline(tokens);
    const safe = safeHref(href);
    if (!safe) return label;
    const titleAttr = title ? ` title="${escapeHtml(title)}"` : "";
    return `<a href="${escapeHtml(safe)}"${titleAttr} rel="nofollow ugc">${label}</a>`;
  };
  renderer.image = ({ href, title, text }) => {
    const safe = safeHref(href, true);
    if (!safe) return escapeHtml(text);
    const titleAttr = title ? ` title="${escapeHtml(title)}"` : "";
    return `<img src="${escapeHtml(safe)}" alt="${escapeHtml(text)}"${titleAttr}>`;
  };
  return marked.parse(markdown, {
    async: false,
    breaks: true,
    gfm: true,
    renderer,
  }) as string;
}

function markdownContent(value: UnknownRecord): string | null {
  const content = recordObject(value.content);
  if (content?.$type !== "at.markpub.markdown") return null;
  const text = recordObject(content.text);
  return stringField(text ?? {}, "markdown");
}

function documentSummary(
  did: string,
  publicationRkey: string,
  uri: string,
  value: UnknownRecord,
): StandardSiteDocumentSummary | null {
  const match = /^at:\/\/[^/]+\/site\.standard\.document\/([^/?#]+)$/.exec(uri);
  const rkey = match?.[1] ?? "";
  if (!isTid(rkey)) return null;
  const expectedSite = publicationAtUri(did, publicationRkey);
  const expectedPath = standardSiteDocumentPath(rkey);
  const title = stringField(value, "title")?.trim();
  const publishedAt = stringField(value, "publishedAt");
  if (
    value.$type !== STANDARD_SITE_DOCUMENT_COLLECTION ||
    value.site !== expectedSite ||
    value.path !== expectedPath ||
    !title ||
    !publishedAt ||
    Number.isNaN(Date.parse(publishedAt))
  ) {
    return null;
  }
  return {
    uri: documentAtUri(did, rkey),
    rkey,
    title,
    description: stringField(value, "description")?.trim() || null,
    publishedAt,
    updatedAt: stringField(value, "updatedAt"),
    url: standardSiteDocumentUrl(did, publicationRkey, rkey),
  };
}

export function standardSiteRouteDid(segment: string): string {
  const did = decodeStandardSiteDid(segment);
  if (!did) throw new Error("Invalid ATProto DID route");
  return did;
}

export async function loadStandardSitePublication(
  did: string,
  publicationRkey: string,
  fetcher: Fetcher = fetch,
): Promise<StandardSitePublicationPage> {
  if (!isTid(publicationRkey)) throw new Error("Invalid publication key");
  const pds = await resolvePds(did, fetcher);
  const publicationValue = await getRecord(
    did,
    STANDARD_SITE_PUBLICATION_COLLECTION,
    publicationRkey,
    fetcher,
    pds,
  );
  const publication = parsePublication(did, publicationRkey, publicationValue);
  const records = await listDocumentRecords(did, fetcher, pds);
  const documents = records
    .map(({ uri, value }) =>
      documentSummary(did, publicationRkey, uri, value),
    )
    .filter((document): document is StandardSiteDocumentSummary => !!document)
    .sort(
      (a, b) => Date.parse(b.publishedAt) - Date.parse(a.publishedAt),
    );
  return { publication, documents };
}

export async function loadStandardSiteDocument(
  did: string,
  publicationRkey: string,
  documentRkey: string,
  fetcher: Fetcher = fetch,
): Promise<StandardSiteDocumentPage> {
  if (!isTid(publicationRkey) || !isTid(documentRkey)) {
    throw new Error("Invalid Standard.site record key");
  }
  const pds = await resolvePds(did, fetcher);
  const [publicationValue, documentValue] = await Promise.all([
    getRecord(
      did,
      STANDARD_SITE_PUBLICATION_COLLECTION,
      publicationRkey,
      fetcher,
      pds,
    ),
    getRecord(
      did,
      STANDARD_SITE_DOCUMENT_COLLECTION,
      documentRkey,
      fetcher,
      pds,
    ),
  ]);
  const publication = parsePublication(did, publicationRkey, publicationValue);
  const uri = documentAtUri(did, documentRkey);
  const summary = documentSummary(
    did,
    publicationRkey,
    uri,
    documentValue,
  );
  if (!summary) throw new Error("Standard.site document is not verified for this URL");
  const markdown = markdownContent(documentValue);
  const textContent = stringField(documentValue, "textContent") ?? "";
  const html = markdown
    ? renderStandardSiteMarkdown(markdown)
    : `<p>${escapeHtml(textContent).replace(/\n{2,}/g, "</p><p>").replace(/\n/g, "<br>")}</p>`;
  return {
    publication,
    document: { ...summary, textContent, markdown, html },
  };
}
